using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Preserve EF Core 8 discriminator property name ("Discriminator" instead of new default "$type").
            // Required: 500K existing documents use c.Discriminator, and direct SQL queries reference it.
            entity.HasDiscriminator<string>("Discriminator");

            // Preserve EF Core 8 compound id format ("Product|123" instead of new default "123").
            // Required: existing documents were written with the old format.
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // REMOVED: HasIndex() now throws for Cosmos DB entities.
        // Manage indexing via Azure Portal / Bicep / Terraform indexing policy instead.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

